-- 0011: category labels, colors, classifier descriptions and public blurbs move from
-- code (packages/core categories.ts, apps/ingest classifier.ts) into a setting, so
-- categories can be added, edited and renamed from /admin/taxonomy without a deploy.
-- The `categories` list keeps its shape: it is still the classifier's enum and the
-- display order. The hints are copied word for word, so the classifier prompt (and its
-- fingerprint) stays the same.
INSERT INTO settings (key, value) VALUES ('category_info', '{"agent":{"label":"Agent","hue":"violet","hint":"coding agents that plan and make changes on their own","blurb":"Coding agents that plan and make changes on their own."},"agent-addon":{"label":"Agent add-on","hue":"indigo","hint":"add-ons installed into a coding agent (Claude Code, Codex, Cursor and similar): plugins, skills, hooks, mods, status lines, rule and prompt packs; security add-ons are agent-security","blurb":"Plugins, skills, hooks, status lines and rule packs you install into a coding agent."},"agent-tools":{"label":"Agent tools","hue":"sky","hint":"tools made for coding agents that run alongside them: running agents in parallel, dashboards and monitoring, usage and cost tracking, remote control, sandboxes for coding agents; security tools are agent-security","blurb":"Tools that run alongside coding agents: parallel runs, dashboards, cost tracking, sandboxes."},"agent-security":{"label":"Agent security","hue":"rose","hint":"tools that keep coding agents safe: guardrails and policy gates, blocking dangerous commands, catching leaked secrets, audit trails of what an agent did, pinning MCP tools","blurb":"Guardrails, command blocking, secret scanning and audit trails for coding agents."},"review-testing":{"label":"Review & testing","hue":"orange","hint":"AI code review, test generation, and checking AI-written code","blurb":"AI code review, test generation, and checking what the AI wrote."},"memory-context":{"label":"Memory & context","hue":"cyan","hint":"memory for coding agents, codebase docs or indexes made for agents, and tools that keep an agent''s context small","blurb":"Memory, codebase indexes and context trimming for coding agents."},"ide":{"label":"IDE","hue":"blue","hint":"AI IDEs and editor extensions","blurb":"AI editors and editor extensions."},"cli":{"label":"CLI","hue":"amber","hint":"AI command-line tools whose job fits none of the more specific categories","blurb":"AI command-line tools that fit nowhere more specific."},"mcp-dev":{"label":"MCP · dev","hue":"teal","hint":"MCP servers for software development work (code hosts, databases, deployment, testing, error tracking, docs)","blurb":"MCP servers for software development."},"mcp-general":{"label":"MCP · general","hue":"pink","hint":"MCP servers for anything else (data, analytics, research, productivity, commerce)","blurb":"MCP servers for everything else."},"other":{"label":"Other","hue":"stone","hint":"an in-scope tool that fits none of the other categories","blurb":"AI dev tools that fit no other category yet."}}')
  ON CONFLICT (key) DO NOTHING;
